using NUnit.Framework;

namespace Depths.Tests
{
    /// <summary>
    /// The lunger against the running game. Every row was recorded by tools/lunger-parity.js on
    /// 2026-10-06 from the game's own tickBodies(): seed 4242, the player held still, Rnd reseeded
    /// before the first tick, every 10th tick compared (position, state, lungeT, curSpeed, knock
    /// velocity, and the player's hp) to 1e-6, and the jitter draws counted exactly.
    /// </summary>
    [TestFixture]
    public sealed class LungerParityTests
    {
        static void Check(double[] player, double[][] bodies, int ticks, int jitterDraws, object[][] rows)
        {
            var run = new RunState(new Rng(4242)) { dungeon = Dungeon.FromSeed(new Rng(4242)) };
            run.state = "playing";
            var p = run.player;
            p.x = p.lagX = player[0]; p.y = p.lagY = player[1];
            p.hp = p.maxHp = 1e6;
            TickOrder.HitboxX = p.lagX; TickOrder.HitboxY = p.lagY;
            for (int i = 0; i < bodies.Length; i++)
            {
                var b = bodies[i];
                var e = Enemy.Of(BodyKind.Lunger, b[0], b[1]);
                e.noticeTimer = 0; e.aggroTimer = 0; e.kvx = b[2]; e.kvy = b[3];
                e.flank = i * 2.399963229728653; e.idleTimer = (int)b[4]; e.curSpeed = b[5];
                run.enemies.Add(e);
            }
            int j0 = run.rng.JitterCalls, r0 = run.rng.RunCalls, row = 0;
            for (int t = 1; t <= ticks; t++)
            {
                p.iframes = 0;
                TickOrder.TickBodies(run);
                if (t % 10 != 0) continue;
                var want = rows[row++];
                Assert.That(t, Is.EqualTo(System.Convert.ToInt32(want[0])));
                Assert.That(p.hp, Is.EqualTo(System.Convert.ToDouble(want[1])).Within(1e-6), "player hp at tick " + t);
                for (int i = 0; i < run.enemies.Count; i++)
                {
                    var e = run.enemies[i];
                    int o = 2 + i * 7;
                    string at = " (body " + i + ", tick " + t + ")";
                    Assert.That(e.x, Is.EqualTo(System.Convert.ToDouble(want[o])).Within(1e-6), "x" + at);
                    Assert.That(e.y, Is.EqualTo(System.Convert.ToDouble(want[o + 1])).Within(1e-6), "y" + at);
                    Assert.That(e.lungeState, Is.EqualTo((string)want[o + 2]), "state" + at);
                    Assert.That(e.lungeT, Is.EqualTo(System.Convert.ToInt32(want[o + 3])), "lungeT" + at);
                    Assert.That(e.curSpeed, Is.EqualTo(System.Convert.ToDouble(want[o + 4])).Within(1e-6), "curSpeed" + at);
                    Assert.That(e.kvx, Is.EqualTo(System.Convert.ToDouble(want[o + 5])).Within(1e-6), "kvx" + at);
                    Assert.That(e.kvy, Is.EqualTo(System.Convert.ToDouble(want[o + 6])).Within(1e-6), "kvy" + at);
                }
            }
            Assert.That(run.rng.JitterCalls - j0, Is.EqualTo(jitterDraws), "jitter draws");
            Assert.That(run.rng.RunCalls - r0, Is.Zero, "the body phase drew from the run stream");
        }

